s=Path(__file__).parent;fr=json.loads((s/'input-freeze.json').read_text());pr=json.loads((s/'prediction-freeze.json').read_text());assert json.loads((s/'verification.json').read_text())['status']=='pass-all-weights-models-inner-study-losses-and-predictions';assert hashlib.sha256((s/'cohorts.npz').read_bytes()).hexdigest()==fr['cohortsSHA256'];assert hashlib.sha256((s/'cohort-metadata.json').read_bytes()).hexdigest()==fr['metadataSHA256'];meta=json.loads((s/'cohort-metadata.json').read_text());arrays=np.load(s/'cohorts.npz');out={'scope':'Three-study development reuse, with outer held-out studies and inner training-study selection. Not untouched external validation; source participant overlap beyond study labels unverified.','folds':{},'predictionFreezeSHA256':hashlib.sha256((s/'prediction-freeze.json').read_bytes()).hexdigest()}
